export function PromptIcon({
  name,
  className,
}: {
  name: PromptKey
  className?: string
}) {
  return (
    <svg
      viewBox="0 0 32 32"
      role="presentation"
      aria-hidden="true"
      focusable="false"
      fill="currentColor"
      className={cn("block h-6 w-6 shrink-0", className)}
    >
      {PROMPT_ICON_PATHS[name].map((d, i) => (
        <path key={i} d={d} />
      ))}
    </svg>
  )
}

